-- All chains listed on DEX Screener that Lockabox knows by id (owner request 2026-09-27). They get DEX Screener discovery, snapshots,
-- the liquidity gate and "View on DEX Screener"; in-app swap stays off (no rpc_url, DECISIONS #10) and DexPaprika new-pool
-- discovery stays on the original six chains only (free credit budget). Ids first seen in recorded feeds: avalanche, near, ton,
-- pulsechain, tron; the rest follow DEX Screener's URLs and should be checked against live feeds. The worker also registers any
-- chain id it meets in a DEX Screener feed that is not listed here (worker/ingest.ts `registerChains`).
alter table chains drop constraint chains_family_check;
alter table chains add constraint chains_family_check check (family in ('solana', 'evm', 'other'));

on conflict (id) do nothing;
